1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"sort"
10		"strings"
11	)
12	
13	// Reason constants for clusters that cannot enter a release plan.
14	const (
15		ReasonDisabled          = "集群已停用"
16		ReasonExcludeMatched    = "命中排除条件"
17		ReasonIncludeNotMatched = "未命中包含条件"
18	)
19	
20	// LabelCondition is a set of exact key-value matches; all must match.
21	type LabelCondition map[string]string
22	
23	// Cluster is a candidate target for a release.
24	type Cluster struct {
25		ID       string
26		Disabled bool
27		Tags     map[string]string
28	}
29	
30	// ReleasePlanInput describes an application release to plan offline.
31	type ReleasePlanInput struct {
32		App       string
33		Revision  string
34		Image     string
35		BatchSize int
36		Clusters  []Cluster
37		Include   []LabelCondition
38		Exclude   []LabelCondition
39		// SpreadBy, when non-empty, names a cluster tag whose value identifies a
40		// fault domain; each batch then contains at most one cluster per domain.
41		SpreadBy string
42	}
43	
44	// AppInfo identifies the application being released.
45	type AppInfo struct {
46		Name     string `json:"name"`
47		Revision string `json:"revision"`
48		Image    string `json:"image"`
49	}
50	
51	// Batch is a sequentially numbered group of cluster IDs.
52	type Batch struct {
53		Index    int      `json:"index"`
54		Clusters []string `json:"clusters"`
55	}
56	
57	// ExcludedCluster explains why a cluster is not in the plan.
58	type ExcludedCluster struct {
59		ID     string `json:"id"`
60		Reason string `json:"reason"`
61	}
62	
63	// ReleasePlan is the deterministic offline release plan.
64	type ReleasePlan struct {
65		App      AppInfo           `json:"app"`
66		Batches  []Batch           `json:"batches"`
67		Excluded []ExcludedCluster `json:"excluded"`
68	}
69	
70	// ParseReleaseInput reads a release plan document and validates its fields.
71	// Every JSON object in the document — including unknown fields and their
72	// nested objects — must have distinct member names; a name appearing twice
73	// (even with the same value, or via equivalent Unicode escapes) is rejected
74	// before any business validation runs.
75	func ParseReleaseInput(data []byte) (ReleasePlanInput, error) {
76		if err := checkDuplicateMembers(data); err != nil {
77			return ReleasePlanInput{}, err
78		}
79		dec := json.NewDecoder(bytes.NewReader(data))
80		dec.UseNumber()
81		var doc map[string]any
82		if err := dec.Decode(&doc); err != nil {
83			return ReleasePlanInput{}, fmt.Errorf("JSON 格式错误: %w", err)
84		}
85		if dec.More() {
86			return ReleasePlanInput{}, errors.New("JSON 格式错误: 文档包含多余内容")
87		}
88		return buildReleaseInput(doc)
89	}
90	
91	// duplicateMemberError reports a JSON object whose member name appears more
92	// than once. Path is a JSONPath-style location that points at the object
93	// owning the duplicate (the duplicate member name itself is reported
94	// separately in field): "$" for the document root, "$.clusters[1]" for a
95	// cluster, "$.clusters[0].tags" for a tag object,
96	// "$.include[2]" / "$.exclude[1]" for a condition, and "$.foo.bar[0]" for
97	// objects nested inside unknown fields. A member name that is not a plain
98	// identifier is wrapped in brackets around a JSON string, so that characters
99	// in the name can never be read as hierarchy or an array index: a top-level
100	// member "meta.info" is at $["meta.info"] (distinct from the nested object
101	// $.meta.info), "zone[0]" stays one whole name at $["zone[0]"], and names
102	// that are empty or contain quotes, backslashes or control characters are
103	// rendered as decodable JSON strings such as $[""] or $["a\nb"].
104	type duplicateMemberError struct {
105		field string
106		path  string
107	}
108	
109	func (e *duplicateMemberError) Error() string {
110		return fmt.Sprintf("JSON 对象存在重复成员: 字段 %q 重复出现于 %s", e.field, e.path)
111	}
112	
113	// checkDuplicateMembers walks every JSON object in data and rejects objects
114	// with duplicate member names. Names are compared after JSON decoding, so
115	// "env" and "env" are the same name while "env" and "ENV", or
116	// " env" and "env", are different. The first duplicate encountered in file
117	// order is reported: the walk is depth-first in document order, so the
118	// second occurrence that appears earliest wins, regardless of value type.
119	func checkDuplicateMembers(data []byte) error {
120		dec := json.NewDecoder(bytes.NewReader(data))
121		// Numbers are only walked past, never interpreted: UseNumber keeps legal
122		// JSON numbers beyond float64 range (e.g. 1e400) from being turned into an
123		// unmarshal-overflow error here. Whether a number is acceptable for a given
124		// field is decided later by business validation.
125		dec.UseNumber()
126		if err := walkJSONValue(dec, "$"); err != nil {
127			return err
128		}
129		if _, err := dec.Token(); err != io.EOF {
130			if err == nil {
131				return errors.New("JSON 格式错误: 文档包含多余内容")
132			}
133			return fmt.Errorf("JSON 格式错误: %w", err)
134		}
135		return nil
136	}
137	
138	// walkJSONValue reads one complete JSON value whose first token has not been
139	// consumed yet.
140	func walkJSONValue(dec *json.Decoder, path string) error {
141		tok, err := dec.Token()
142		if err != nil {
143			if err == io.EOF {
144				return errors.New("JSON 格式错误: 文档为空")
145			}
146			return fmt.Errorf("JSON 格式错误: %w", err)
147		}
148		return walkJSONValueToken(dec, path, tok)
149	}
150	
151	// walkJSONValueToken reads the remainder of a value given its first token.
152	func walkJSONValueToken(dec *json.Decoder, path string, tok json.Token) error {
153		if d, ok := tok.(json.Delim); ok {
154			switch d {
155			case '{':
156				return walkJSONObject(dec, path)
157			case '[':
158				return walkJSONArray(dec, path)
159			default:
160				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
161			}
162		}
163		return nil // scalar value (string, number, bool, null)
164	}
165	
166	func walkJSONObject(dec *json.Decoder, path string) error {
167		seen := make(map[string]struct{})
168		for {
169			tok, err := dec.Token()
170			if err != nil {
171				if err == io.EOF {
172					return errors.New("JSON 格式错误: 对象未闭合")
173				}
174				return fmt.Errorf("JSON 格式错误: %w", err)
175			}
176			if d, ok := tok.(json.Delim); ok {
177				if d == '}' {
178					return nil
179				}
180				return fmt.Errorf("JSON 格式错误: 意外的分隔符 %q", d)
181			}
182			key, ok := tok.(string)
183			if !ok {
184				return errors.New("JSON 格式错误: 对象成员名必须是字符串")
185			}
186			if _, dup := seen[key]; dup {
187				return &duplicateMemberError{field: key, path: path}
188			}
189			seen[key] = struct{}{}
190			vtok, err := dec.Token()
191			if err != nil {
192				if err == io.EOF {
193					return errors.New("JSON 格式错误: 缺少成员值")
194				}
195				return fmt.Errorf("JSON 格式错误: %w", err)
196			}
197			if err := walkJSONValueToken(dec, joinMemberPath(path, key), vtok); err != nil {
198				return err
199			}
200		}
201	}
202	
203	// isSimpleMemberName reports whether key may be written with dot notation:
204	// it must start with an ASCII letter or underscore and contain only ASCII
205	// letters, digits, and underscores afterward.
206	func isSimpleMemberName(key string) bool {
207		if key == "" {
208			return false
209		}
210		for i, r := range key {
211			switch {
212			case r == '_' || ('a' <= r && r <= 'z') || ('A' <= r && r <= 'Z'):
213			case i > 0 && ('0' <= r && r <= '9'):
214			default:
215				return false
216			}
217		}
218		return true
219	}
220	
221	// joinMemberPath extends an object location with one member name. Simple
222	// identifier names keep the existing dot spelling ("$.clusters[0].tags");
223	// every other name is rendered as brackets around a JSON-encoded string, so
224	// the text decodes back to exactly the real member name and none of its
225	// characters can be mistaken for a path separator or array index.
226	func joinMemberPath(path, key string) string {
227		if isSimpleMemberName(key) {
228			return path + "." + key
229		}
230		return path + "[" + jsonEncodePathString(key) + "]"
231	}
232	
233	// jsonEncodePathString renders key as a legal JSON string (including the
234	// surrounding quotes); decoding the result restores key exactly, including
235	// empty names and names containing quotes, backslashes, newlines or other
236	// control characters.
237	func jsonEncodePathString(key string) string {
238		bs, err := json.Marshal(key)
239		if err != nil {
240			// json.Marshal cannot fail for a Go string.
241			panic(fmt.Sprintf("json.Marshal(%q): %v", key, err))
242		}
243		return string(bs)
244	}
245	
246	func walkJSONArray(dec *json.Decoder, path string) error {
247		for i := 0; ; i++ {
248			tok, err := dec.Token()
249			if err != nil {
250				if err == io.EOF {
251					return errors.New("JSON 格式错误: 数组未闭合")
252				}
253				return fmt.Errorf("JSON 格式错误: %w", err)
254			}
255			if d, ok := tok.(json.Delim); ok && d == ']' {
256				return nil
257			}
258			if err := walkJSONValueToken(dec, fmt.Sprintf("%s[%d]", path, i), tok); err != nil {
259				return err
260			}
261		}
262	}
263	
264	func buildReleaseInput(doc map[string]any) (ReleasePlanInput, error) {
265		app, err := requiredString(doc, "app")
266		if err != nil {
267			return ReleasePlanInput{}, err
268		}
269		revision, err := requiredString(doc, "revision")
270		if err != nil {
271			return ReleasePlanInput{}, err
272		}
273		image, err := requiredString(doc, "image")
274		if err != nil {
275			return ReleasePlanInput{}, err
276		}
277		batchSize, err := positiveInt(doc, "batchSize")
278		if err != nil {
279			return ReleasePlanInput{}, err
280		}
281		spreadBy, err := optionalSpreadBy(doc)
282		if err != nil {
283			return ReleasePlanInput{}, err
284		}
285		clusters, err := parseClusters(doc["clusters"])
286		if err != nil {
287			return ReleasePlanInput{}, err
288		}
289		include, err := parseConditions(doc["include"], "include")
290		if err != nil {
291			return ReleasePlanInput{}, err
292		}
293		exclude, err := parseConditions(doc["exclude"], "exclude")
294		if err != nil {
295			return ReleasePlanInput{}, err
296		}
297	
298		return ReleasePlanInput{
299			App:       app,
300			Revision:  revision,
301			Image:     image,
302			BatchSize: batchSize,
303			Clusters:  clusters,
304			Include:   include,
305			Exclude:   exclude,
306			SpreadBy:  spreadBy,
307		}, nil
308	}
309	
310	// optionalSpreadBy reads the optional "spreadBy" field: absent or an empty
311	// string disables fault-domain spreading; a non-string value or a string of
312	// only whitespace is rejected. The tag key is used exactly as written.
313	func optionalSpreadBy(doc map[string]any) (string, error) {
314		v, ok := doc["spreadBy"]
315		if !ok {
316			return "", nil
317		}
318		s, ok := v.(string)
319		if !ok {
320			return "", fmt.Errorf("字段 %q 必须是字符串", "spreadBy")
321		}
322		if err := checkSpreadBy(s); err != nil {
323			return "", err
324		}
325		return s, nil
326	}
327	
328	// checkSpreadBy rejects a spreadBy value that is neither empty nor a usable
329	// tag key: a string of only whitespace can never match a valid tag key.
330	func checkSpreadBy(s string) error {
331		if s != "" && strings.TrimSpace(s) == "" {
332			return fmt.Errorf("字段 %q 不能只含空白", "spreadBy")
333		}
334		return nil
335	}
336	
337	// ValidateReleaseInput checks that a release configuration is well-formed:
338	// app/revision/image are non-empty, batchSize is a positive integer, spreadBy
339	// is empty or a usable tag key (not whitespace-only), cluster
340	// IDs are unique across every candidate (including disabled and filtered-out
341	// clusters), and tag/condition keys are non-empty. Errors name the field and
342	// the position in its list; within a cluster the ID is checked before its
343	// tags, and tag keys are examined in ascending order so repeated calls report
344	// the same error. The input is never mutated. MakeReleasePlan calls this
345	// automatically; library callers may use it to validate without planning.
346	func ValidateReleaseInput(in ReleasePlanInput) error {
347		if strings.TrimSpace(in.App) == "" {
348			return errors.New(`字段 "app" 不能为空或只含空白`)
349		}
350		if strings.TrimSpace(in.Revision) == "" {
351			return errors.New(`字段 "revision" 不能为空或只含空白`)
352		}
353		if strings.TrimSpace(in.Image) == "" {
354			return errors.New(`字段 "image" 不能为空或只含空白`)
355		}
356		if in.BatchSize <= 0 {
357			return errors.New(`字段 "batchSize" 必须是正整数`)
358		}
359		if err := checkSpreadBy(in.SpreadBy); err != nil {
360			return err
361		}
362		seen := make(map[string]struct{}, len(in.Clusters))
363		for i, c := range in.Clusters {
364			if strings.TrimSpace(c.ID) == "" {
365				return fmt.Errorf("clusters[%d]: 字段 %q 不能为空或只含空白", i, "id")
366			}
367			if _, dup := seen[c.ID]; dup {
368				return fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, c.ID)
369			}
370			seen[c.ID] = struct{}{}
371			if err := validateTagKeys(i, c.Tags); err != nil {
372				return err
373			}
374		}
375		if err := validateConditionKeys("include", in.Include); err != nil {
376			return err
377		}
378		if err := validateConditionKeys("exclude", in.Exclude); err != nil {
379			return err
380		}
381		return nil
382	}
383	
384	// validateTagKeys applies the shared label-key rule to one cluster's tags,
385	// reporting the cluster's position in the candidate list.
386	func validateTagKeys(clusterIndex int, tags map[string]string) error {
387		if hasEmptyLabelKey(tags) {
388			return fmt.Errorf("clusters[%d] 的标签键不能为空", clusterIndex)
389		}
390		return nil
391	}
392	
393	// validateConditionKeys applies the shared condition rules to every condition
394	// in original order, so the first invalid condition is reported.
395	func validateConditionKeys(field string, conds []LabelCondition) error {
396		for i, cond := range conds {
397			if err := validateCondition(field, i, cond); err != nil {
398				return err
399			}
400		}
401		return nil
402	}
403	
404	func requiredString(doc map[string]any, field string) (string, error) {
405		v, ok := doc[field]
406		if !ok {
407			return "", fmt.Errorf("缺少必需字段 %q", field)
408		}
409		s, ok := v.(string)
410		if !ok {
411			return "", fmt.Errorf("字段 %q 必须是字符串", field)
412		}
413		if strings.TrimSpace(s) == "" {
414			return "", fmt.Errorf("字段 %q 不能为空或只含空白", field)
415		}
416		return s, nil
417	}
418	
419	func positiveInt(doc map[string]any, field string) (int, error) {
420		v, ok := doc[field]
421		if !ok {
422			return 0, fmt.Errorf("缺少必需字段 %q", field)
423		}
424		n, ok := v.(json.Number)
425		if !ok {
426			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
427		}
428		i, err := n.Int64()
429		if err != nil || i <= 0 {
430			return 0, fmt.Errorf("字段 %q 必须是正整数", field)
431		}
432		return int(i), nil
433	}
434	
435	func parseClusters(v any) ([]Cluster, error) {
436		if v == nil {
437			return nil, errors.New("缺少必需字段 \"clusters\"")
438		}
439		raw, ok := v.([]any)
440		if !ok {
441			return nil, errors.New("字段 \"clusters\" 必须是数组")
442		}
443		clusters := make([]Cluster, 0, len(raw))
444		seen := make(map[string]bool)
445		for i, item := range raw {
446			obj, ok := item.(map[string]any)
447			if !ok {
448				return nil, fmt.Errorf("clusters[%d] 必须是对象", i)
449			}
450			id, err := requiredString(obj, "id")
451			if err != nil {
452				return nil, fmt.Errorf("clusters[%d]: %w", i, err)
453			}
454			if seen[id] {
455				return nil, fmt.Errorf("clusters[%d]: 重复的集群标识 %q", i, id)
456			}
457			seen[id] = true
458	
459			disabled := false
460			if dv, present := obj["disabled"]; present {
461				b, ok := dv.(bool)
462				if !ok {
463					return nil, fmt.Errorf("集群 %q 的 \"disabled\" 必须是布尔值", id)
464				}
465				disabled = b
466			}
467	
468			tags := map[string]string{}
469			if tv, present := obj["tags"]; present {
470				tm, ok := tv.(map[string]any)
471				if !ok {
472					return nil, fmt.Errorf("集群 %q 的 \"tags\" 必须是对象", id)
473				}
474				tags, err = labelsFromJSON(tm,
475					func(string) error { return fmt.Errorf("集群 %q 的标签键不能为空", id) },
476					func(k string) error { return fmt.Errorf("集群 %q 的标签 %q 值必须是字符串", id, k) },
477				)
478				if err != nil {
479					return nil, err
480				}
481			}
482	
483			clusters = append(clusters, Cluster{ID: id, Disabled: disabled, Tags: tags})
484		}
485		return clusters, nil
486	}
487	
488	func parseConditions(v any, field string) ([]LabelCondition, error) {
489		if v == nil {
490			return []LabelCondition{}, nil
491		}
492		raw, ok := v.([]any)
493		if !ok {
494			return nil, fmt.Errorf("字段 %q 必须是条件数组", field)
495		}
496		conds := make([]LabelCondition, 0, len(raw))
497		for i, item := range raw {
498			obj, ok := item.(map[string]any)
499			if !ok {
500				return nil, fmt.Errorf("%s[%d] 必须是对象", field, i)
501			}
502			cond, err := labelsFromJSON(obj,
503				func(string) error { return fmt.Errorf("%s[%d] 的标签键不能为空", field, i) },
504				func(k string) error { return fmt.Errorf("%s[%d] 的标签 %q 值必须是字符串", field, i, k) },
505			)
506			if err != nil {
507				return nil, err
508			}
509			if err := validateCondition(field, i, cond); err != nil {
510				return nil, err
511			}
512			conds = append(conds, cond)
513		}
514		return conds, nil
515	}
516	
517	// MakeReleasePlan selects available clusters, orders them by ID, and splits
518	// them into batches. When SpreadBy names a tag, each batch holds at most one
519	// cluster per value of that tag (its fault domain) and every selected cluster
520	// must carry the tag. It validates the input first and never mutates it.
521	func MakeReleasePlan(in ReleasePlanInput) (ReleasePlan, error) {
522		if err := ValidateReleaseInput(in); err != nil {
523			return ReleasePlan{}, err
524		}
525		if len(in.Clusters) == 0 {
526			return ReleasePlan{}, errors.New("没有可发布的集群：未提供候选集群")
527		}
528	
529		selected := []string{}
530		excluded := []ExcludedCluster{}
531		for _, c := range in.Clusters {
532			switch {
533			case c.Disabled:
534				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonDisabled})
535			case matchesAny(c.Tags, in.Exclude):
536				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonExcludeMatched})
537			case len(in.Include) > 0 && !matchesAny(c.Tags, in.Include):
538				excluded = append(excluded, ExcludedCluster{ID: c.ID, Reason: ReasonIncludeNotMatched})
539			default:
540				selected = append(selected, c.ID)
541			}
542		}
543	
544		sort.Strings(selected)
545		sort.Slice(excluded, func(i, j int) bool { return excluded[i].ID < excluded[j].ID })
546	
547		if len(selected) == 0 {
548			var b strings.Builder
549			b.WriteString("没有符合规则的可用集群，各候选集群未入选原因：")
550			for _, e := range excluded {
551				b.WriteString("\n  ")
552				b.WriteString(e.ID)
553				b.WriteString("：")
554				b.WriteString(e.Reason)
555			}
556			return ReleasePlan{}, errors.New(b.String())
557		}
558	
559		var batches []Batch
560		if in.SpreadBy == "" {
561			batches = chunkBatches(selected, in.BatchSize)
562		} else {
563			domains, err := faultDomains(in.Clusters, selected, in.SpreadBy)
564			if err != nil {
565				return ReleasePlan{}, err
566			}
567			batches = spreadBatches(selected, domains, in.BatchSize)
568		}
569	
570		return ReleasePlan{
571			App:      AppInfo{Name: in.App, Revision: in.Revision, Image: in.Image},
572			Batches:  batches,
573			Excluded: excluded,
574		}, nil
575	}
576	
577	// chunkBatches splits the ascending IDs into batches of at most batchSize.
578	func chunkBatches(selected []string, batchSize int) []Batch {
579		batches := []Batch{}
580		for i := 0; i < len(selected); i += batchSize {
581			end := i + batchSize
582			if end > len(selected) {
583				end = len(selected)
584			}
585			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: selected[i:end]})
586		}
587		return batches
588	}
589	
590	// faultDomains maps every selected cluster ID to the exact value of its
591	// spreadBy tag. A selected cluster missing the tag fails the whole plan;
592	// selected is ascending, so the smallest such ID is reported. An empty
593	// string tag value is a valid fault domain, distinct from a missing tag.
594	func faultDomains(clusters []Cluster, selected []string, spreadBy string) (map[string]string, error) {
595		tagsByID := make(map[string]map[string]string, len(clusters))
596		for _, c := range clusters {
597			tagsByID[c.ID] = c.Tags
598		}
599		domains := make(map[string]string, len(selected))
600		for _, id := range selected {
601			v, ok := tagsByID[id][spreadBy]
602			if !ok {
603				return nil, fmt.Errorf("集群 %q 缺少故障域标签 %q", id, spreadBy)
604			}
605			domains[id] = v
606		}
607		return domains, nil
608	}
609	
610	// spreadBatches packs the ascending IDs into batches of at most batchSize
611	// with at most one cluster per fault domain in each batch. Each batch takes
612	// the smallest still-unscheduled IDs whose domains do not conflict with the
613	// batch; conflicting clusters are deferred to later batches, so a batch may
614	// be short only when no non-conflicting cluster remains. Every ID appears in
615	// exactly one batch and IDs stay ascending within a batch.
616	func spreadBatches(selected []string, domains map[string]string, batchSize int) []Batch {
617		remaining := append([]string(nil), selected...)
618		batches := []Batch{}
619		for len(remaining) > 0 {
620			// The map never holds more entries than there are remaining clusters,
621			// so size it by them — never by batchSize, which is only an upper
622			// bound and may be a huge legal value (e.g. 1e9 meaning "no limit").
623			used := make(map[string]struct{}, min(batchSize, len(remaining)))
624			batch := []string{}
625			deferred := []string{}
626			for _, id := range remaining {
627				d := domains[id]
628				if _, conflict := used[d]; len(batch) < batchSize && !conflict {
629					used[d] = struct{}{}
630					batch = append(batch, id)
631				} else {
632					deferred = append(deferred, id)
633				}
634			}
635			batches = append(batches, Batch{Index: len(batches) + 1, Clusters: batch})
636			remaining = deferred
637		}
638		return batches
639	}
640	
641	func matchesAny(tags map[string]string, conditions []LabelCondition) bool {
642		for _, cond := range conditions {
643			if matchesAll(tags, cond) {
644				return true
645			}
646		}
647		return false
648	}
649	
650	func matchesAll(tags map[string]string, cond LabelCondition) bool {
651		for k, v := range cond {
652			tv, ok := tags[k]
653			if !ok || tv != v {
654				return false
655			}
656		}
657		return true
658	}
659

