package darksafe

import (
	"fmt"
	"strings"
	"testing"
	"time"
)

func parsePlan(t *testing.T, data string) ReleasePlanInput {
	t.Helper()
	in, err := ParseReleaseInput([]byte(data))
	if err != nil {
		t.Fatalf("ParseReleaseInput: %v", err)
	}
	return in
}

func TestPlan_BasicBatchingAndSorting(t *testing.T) {
